//! Fallback fonts chosen like Qt's against real Qt 6.12 (`tests/data/directwrite_fallbacks_golden.txt`,
//! regenerated by `tests/data/gen_directwrite_fallbacks_golden.py`): every script item of a text
//! has its own fallback families (`QWindowsDirectWriteFontDatabase::fallbacksForFamily`: the style
//! hint family, the user's language's `extraTryFonts`, then every family supporting the script),
//! and a character the primary font lacks takes the first family of its item's list with a glyph
//! (`QFontEngineMulti::stringToCMap`). Text in Hangul, Thai, Han, kana, emoji, arrows and symbols
//! against Latin fonts, icon fonts without Latin, and missing families with a style hint: advances
//! and whole strings at device pixel ratios 1 and 1.25.
//!
//! The chain depends on every installed font, so a chunk of the golden (one `fontset` line and the
//! lines below it) is compared only when this machine has the font files it was measured with. The
//! golden holds the chunks of a Windows 11 box and of GitHub's windows-latest. The ratio is
//! process-wide state.
#![cfg(windows)]

use ferrokit_gui::geometry::primitives::PointF;
use ferrokit_gui::paint::{Painter, Pen, Pixmap};
use ferrokit_gui::text::directwrite_face::is_available;
use ferrokit_gui::text::font::{Font, FontWeight, StyleHint};
use ferrokit_gui::text::font_database::set_application_device_pixel_ratio;
use ferrokit_gui::text::font_metrics::FontMetrics;
use ferrokit_gui::text::smoothing::TextSmoothing;
use ferrokit_gui::tiny_skia::Color;

const GOLDEN: &str = include_str!("data/directwrite_fallbacks_golden.txt");

fn fnv1a64(data: &[u8]) -> u64 {
    data.iter().fold(0xcbf2_9ce4_8422_2325u64, |h, &b| {
        (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3)
    })
}

fn text(id: &str) -> &'static str {
    match id {
        "h" => "\u{c548}\u{b155}\u{d558}\u{c138}\u{c694} Hello \u{d55c}\u{ae00}",
        "t" => {
            "\u{e2a}\u{e27}\u{e31}\u{e2a}\u{e14}\u{e35} Hello \u{e20}\u{e32}\u{e29}\u{e32}\u{e44}\u{e17}\u{e22}"
        }
        "c" => "\u{4e2d}\u{6587}\u{5b57} \u{65e5}\u{672c}\u{8a9e} Hello",
        "k" => "\u{3072}\u{3089}\u{304c}\u{306a} \u{30ab}\u{30bf}\u{30ab}\u{30ca} Hello",
        "e" => "Hi \u{1F600}\u{1F389} ok \u{2600} \u{2714}",
        "a" => "a \u{2192} b \u{2190} c \u{21d2} \u{2211} \u{221e}",
        "y" => "\u{a9} \u{ae} \u{2122} \u{20ac} \u{20a9} \u{20b9} \u{bd} \u{2713}",
        "r" => "Hello \u{5e9}\u{5dc}\u{5d5}\u{5dd} \u{645}\u{631}\u{62d}\u{628}\u{627}",
        "m" => "Abc \u{4e2d} \u{d55c} \u{e01} \u{1F600} \u{2192} Z",
        "l" => "Hamburgefonstiv 0123 AVAWTo",
        other => panic!("no text {other}"),
    }
}

fn fixed64(value: f32) -> i64 {
    let fixed = f64::from(value) * 64.0;
    assert_eq!(
        fixed,
        fixed.round(),
        "{value} is not a whole number of 1/64 px"
    );
    fixed as i64
}

fn draw(font: &Font, px: u32, text: &str, dpr: f32) -> (u32, u32, u64) {
    let (w, h) = (360.0 * dpr, ((px * 2 + 15) / 4 * 4) as f32 * dpr);
    let mut pixmap = Pixmap::with_dpr(w.round() as u32, h.round() as u32, dpr).expect("pixmap");
    pixmap.fill(Color::from_rgba8(255, 255, 255, 255));
    {
        let mut painter = Painter::begin(&mut pixmap);
        painter.set_text_smoothing(TextSmoothing {
            cleartype: true,
            gamma: 1.2,
        });
        painter.set_pen(Some(Pen::new(Color::from_rgba8(0, 0, 0, 255), 1.0)));
        painter.draw_text(PointF::new(6.0, px as f32 + 6.0), text, font);
    }
    (
        pixmap.physical_width(),
        pixmap.physical_height(),
        fnv1a64(pixmap.data()),
    )
}

fn hex(field: &str) -> u64 {
    u64::from_str_radix(field, 16).expect("hash")
}

fn hint_of(name: &str) -> StyleHint {
    match name {
        "-" | "AnyStyle" => StyleHint::AnyStyle,
        "OldEnglish" => StyleHint::OldEnglish,
        "Fantasy" => StyleHint::Fantasy,
        "Monospace" => StyleHint::Monospace,
        "Cursive" => StyleHint::Cursive,
        "System" => StyleHint::System,
        other => panic!("hint {other}"),
    }
}

/// `fnv1a64` of the sorted font file names of the machine, as the generator hashes them.
fn fontset() -> (usize, u64) {
    let dir = std::env::var("WINDIR").unwrap_or_else(|_| "C:/Windows".to_string());
    let mut roots = vec![format!("{dir}/Fonts")];
    if let Ok(local) = std::env::var("LOCALAPPDATA") {
        roots.push(format!("{local}/Microsoft/Windows/Fonts"));
    }
    let mut names: Vec<String> = Vec::new();
    for root in roots {
        let mut here: Vec<String> = std::fs::read_dir(root)
            .into_iter()
            .flatten()
            .flatten()
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .collect();
        here.sort();
        names.extend(here);
    }
    (names.len(), fnv1a64(names.join("\n").as_bytes()))
}

#[test]
fn fallback_fonts_per_script_item_are_identical_to_qt() {
    if !is_available() {
        return;
    }
    let (count, hash) = fontset();
    let mut compared = 0;
    let mut failures = Vec::new();
    let mut same_fonts = false;
    for line in GOLDEN
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
    {
        let fields: Vec<&str> = line.split(' ').collect();
        if fields[0] == "fontset" {
            same_fonts = fields[1].parse::<usize>().unwrap() == count && hex(fields[2]) == hash;
            if !same_fonts {
                eprintln!(
                    "skipping the chunk measured with {} font files ({}): this machine has {count} ({hash:016x})",
                    fields[1], fields[2]
                );
            }
            continue;
        }
        if !same_fonts {
            continue;
        }
        // `fb <dpr> <family> <hint> <weight> <px> ...`
        let dpr: f32 = fields[1].parse().expect("dpr");
        let family = fields[2].replace('_', " ");
        let weight: u32 = fields[4].parse().expect("weight");
        let px: u32 = fields[5].parse().expect("size");
        set_application_device_pixel_ratio(dpr);
        let font = Font::new(&family, px as f32)
            .with_style_hint(hint_of(fields[3]))
            .with_weight(if weight >= 600 {
                FontWeight::Bold
            } else {
                FontWeight::Normal
            });
        let rest = &fields[6..];
        let (got, want) = match rest[0] {
            "adv" => {
                let advance =
                    FontMetrics::from_font(&font).horizontal_advance_exact(text(rest[1]), &font);
                (format!("{}", fixed64(advance)), rest[2].to_string())
            }
            "draw" => {
                let (w, h, hash) = draw(&font, px, text(rest[1]), dpr);
                (
                    format!("{w}x{h} {hash:016x}"),
                    format!("{}x{} {:016x}", rest[2], rest[3], hex(rest[4])),
                )
            }
            other => panic!("golden line {other}"),
        };
        compared += 1;
        if got != want {
            failures.push(format!("{line}: {got}, Qt {want}"));
        }
    }
    set_application_device_pixel_ratio(1.0);
    if compared == 0 {
        // The chain depends on every installed font, so a machine with another font set (a new
        // runner image) has nothing to compare until `gen_directwrite_fallbacks_golden.py` has
        // measured it; say so rather than pass quietly.
        eprintln!(
            "NOTHING COMPARED: no chunk of the golden was measured with the {count} font files ({hash:016x}) of this machine"
        );
    }
    assert!(
        failures.is_empty(),
        "{} of {compared} differ from Qt:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
